SELECT id, task_type, callback_group, biz_id, action_time, next_fire_time,
       status, retry_count, created_at, updated_at
FROM timeout_task
WHERE task_type = #{taskType}
  AND biz_id = #{bizId}

mapper.update:
UPDATE timeout_task
SET status         = 'WAITING',
    action_time    = #{actionTime},
    next_fire_time = #{nextFireTime},
    retry_count    = 0,
    updated_at     = #{updatedAt}
WHERE task_type = #{taskType}
  AND biz_id = #{bizId}
  AND status IN ('SUCCESS', 'FAILED', 'CANCELED')

UPDATE timeout_task
SET status     = 'CANCELED',
    updated_at = #{updatedAt}
WHERE task_type = #{taskType}
  AND biz_id = #{bizId}
  AND status IN ('WAITING', 'RETRYING')

UPDATE timeout_task
SET status     = 'SUCCESS',
    updated_at = #{updatedAt}
WHERE task_type = #{taskType}
  AND biz_id IN
  #{bizId}
  AND status IN ('WAITING', 'RETRYING')

UPDATE timeout_task
SET status         = 'RETRYING',
    retry_count    = retry_count + 1,
    next_fire_time = CASE
    WHEN biz_id = #{bizId} THEN #{nextFireTimes[${i}]} 
    ELSE next_fire_time END,
    updated_at     = #{updatedAt}
WHERE task_type = #{taskType}
  AND biz_id IN
  #{bizId}
  AND status IN ('WAITING', 'RETRYING')

UPDATE timeout_task
SET status      = 'FAILED',
    retry_count = retry_count + 1,
    updated_at  = #{updatedAt}
WHERE task_type = #{taskType}
  AND biz_id IN
  #{bizId}
  AND status IN ('WAITING', 'RETRYING')

UPDATE timeout_task
SET status         = 'RETRYING',
    retry_count    = 0,
    next_fire_time = #{nextFireTime},
    updated_at     = #{updatedAt}
WHERE task_type = #{taskType}
  AND biz_id = #{bizId}
  AND status = 'FAILED'

UPDATE timeout_task
SET status     = 'CANCELED',
    updated_at = #{updatedAt}
WHERE task_type = #{taskType}
  AND biz_id = #{bizId}
  AND status = 'FAILED'
